function JapaneseStoryBossDialog:OnBtnListClickHandler()
    UIModule.OpenDialog({
        id = Constants.UITypeIds.ActivityJapaneseStoryBossRankRewardsDialog
    })
end

function JapaneseStoryBossDialog:OnBtnFightHandler()
    local activityContentId = checkNumber(self.activityData.activityContentId) ---排期表中的活动当id来用
    ---@type JapaneseStoryBossPlanVo
    local scheduleVo = CfUtils.GetCfVo(AutoIds.IdSetting6500, "JapaneseStoryBossPlanVo", activityContentId)
    CfUtils.DialogOpen(Constants.UITypeIds.UIFightTeamChoose, { activityUuid = self.activityData.id,
                                                                levelId = scheduleVo.range, upBuffData = self:GetUpBuffData(), upGroup = self.data.upGroup,},
            { { id = Constants.UITypeIds.ActivityJapaneseStoryBossDialog } })
end

function JapaneseStoryBossDialog:GetUpBuffData()
    local data = {}
    for i, v in ipairs(self.data.upGroup) do
        local hasCard = cardComp:IsHasCard(v.refId)
        local tempData = {}
        tempData.refId = v.refId
        tempData.type = v.type
        local index = 1
        if hasCard then
            local cardDojo = cardComp:GetCardByConfId(v.refId)
            local star = cardDojo.star
            index = star + 1
            
        end
        tempData.commonAddId = v.additions[index].commonAddId
        table.insert(data,tempData)
    end
    return data
end

function JapaneseStoryBossDialog:OnBtnRewardHandler()

end

