    ---@type ActivityCakeBossLevelVo
    local questVo = CfUtils.GetCfVo(AutoIds.IdSetting6498, "JapaneseStoryBossQuestVo", scheduleVo.range)
    CfUtils.DialogOpen(Constants.UITypeIds.ActivityJapaneseStoryBossDetailsDialog, { planVo = scheduleVo, questVo = questVo }, { { id = Constants.UITypeIds.ActivityJapaneseStoryBossDialog } })
end
